import sys, struct, pickle; sys.path.insert(0,'tools')
from disasm import parse_elf
from capstone import Cs, CS_ARCH_ARM64, CS_MODE_LITTLE_ENDIAN

def plt_map(path):
    data,secs,syms=parse_elf(path)
    sec={s['name']:s for s in secs}
    dynstr=sec['.dynstr']; strb=data[dynstr['offset']:dynstr['offset']+dynstr['size']]
    def z(b,o): return b[o:b.index(b'\x00',o)].decode()
    dynsym=sec['.dynsym']; symdata=data[dynsym['offset']:dynsym['offset']+dynsym['size']]
    def symname(idx): return z(strb,struct.unpack('<I',symdata[idx*24:idx*24+4])[0])
    rela=sec.get('.rela.plt')
    plt=sec['.plt']; pm={}
    rdata=data[rela['offset']:rela['offset']+rela['size']]
    for i in range(0,len(rdata),24):
        off,info,add=struct.unpack('<QQq',rdata[i:i+24])
        pm[plt['addr']+0x20+(i//24)*0x10]=symname(info>>32)
    return pm

def scan(path,a0,a1,label):
    data,secs,syms=parse_elf(path)
    pm=plt_map(path)
    text=next(s for s in secs if s['name']=='.text')
    code=data[text['offset']:text['offset']+text['size']]; base=text['addr']
    md=Cs(CS_ARCH_ARM64,CS_MODE_LITTLE_ENDIAN)
    calls={}
    for ins in md.disasm(code[a0-base:a1-base], a0):
        if ins.mnemonic=='bl':
            try: t=int(ins.op_str.lstrip('#'),16)
            except: continue
            nm=pm.get(t)
            if nm and ('cxa' in nm or nm=='abort'): calls.setdefault(nm,[]).append(hex(ins.address))
    print(label, calls if calls else 'NO cxa/abort calls')

